PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE `assets` (
	`id` text PRIMARY KEY,
	`filename` text NOT NULL,
	`mime_type` text NOT NULL,
	`size` integer NOT NULL,
	`width` integer,
	`height` integer,
	`alt` text,
	`title` text,
	`r2_key` text NOT NULL,
	`blurhash` text,
	`colors` text,
	`focal_point` text,
	`tags` text DEFAULT '[]',
	`created_at` text NOT NULL
, "custom_data" text DEFAULT '{}', "updated_at" text, "created_by" text, "updated_by" text, basename TEXT, format TEXT);
